code.formula:
@Command([EditDocument]; "1");

@If (Comp = ""; 			@Return(@Do(@Command([EditGotoField];"Comp");			@Prompt([Ok];"Missing Value"; "Please select 'Company' before proceeding!")));"");
@If (Dept = ""; 				@Return(@Do(@Command([EditGotoField];"Dept");				@Prompt([Ok];"Missing Value"; "Please select 'Department' before proceeding!")));"");
@If (tSection = ""; 			@Return(@Do(@Command([EditGotoField];"tSection");		@Prompt([Ok];"Missing Value"; "Please specify 'Section' before proceeding!")));"");
@If (HOD = ""; 				@Return(@Do(@Command([EditGotoField];"HOD");				@Prompt([Ok];"Missing Value"; "Please select the HOD!")));"");
@If (HODiv = ""; 			@Return(@Do(@Command([EditGotoField];"HODiv");			@Prompt([Ok];"Missing Value"; "Please select the Division Head!")));"");
@If (rExecutive = ""; 		@Return(@Do(@Command([EditGotoField];"rExecutive");	@Prompt([Ok];"Missing Value"; "Please select either 'Executive/Non-Executive' before proceeding!")));"");
@If (nNumber = ""; 		@Return(@Do(@Command([EditGotoField];"nNumber");		@Prompt([Ok];"Missing Value"; "Please specify the 'number' before proceeding!")));"");
@If (RecType = "" ; 		@Return(@Do(@Command([EditGotoField];"RecType");		@Prompt([Ok];"Missing Value"; "Please state the Recruitment type!")));"");
@If (rStatus = ""; 			@Return(@Do(@Command([EditGotoField];"rStatus");			@Prompt([Ok];"Missing Value"; "Please select 'Status' before proceeding!")));"");
@If (rStatus != "Permanent" & tTermPeriod = "" ;
									@Return(@Do(@Command([EditGotoField];"tTermPeriod");	@Prompt([Ok];"Missing Value"; "Please state the term period before proceeding!")));"");

@If (tReason = ""; 		@Return(@Do(@Command([EditGotoField];"tReason");		@Prompt([Ok];"Missing Value"; "Please specify the 'Reason' before proceeding!")));"");
@If (tDuties = ""; 			@Return(@Do(@Command([EditGotoField];"tDuties");			@Prompt([Ok];"Missing Value"; "Please insert 'Duties' before proceeding!")));"");

@If (Designation = "";	@Return(@Do(@Command([EditGotoField];"Designation");	@Prompt([Ok];"Missing Value"; "Please insert 'Designation' before proceeding!")));"");
@If (tQualification = "";	@Return(@Do(@Command([EditGotoField];"tQualification");	@Prompt([Ok];"Missing Value"; "Please insert 'Qualification' before proceeding!")));"");
@If (tExperience= ""; 	@Return(@Do(@Command([EditGotoField];"tExperience");	@Prompt([Ok];"Missing Value"; "Please insert 'Experience' before proceeding!")));"");
@If (JobProfile= ""; 		@Return(@Do(@Command([EditGotoField];"JobProfile");		@Prompt([Ok];"Missing Value"; "Please insert 'Job Profile' before proceeding!")));"");

@If (Age= ""; 				@Return(@Do(@Command([EditGotoField];"Age");				@Prompt([Ok];"Missing Value"; "Please insert 'Age' before proceeding!")));"");
@If (Gender= ""; 			@Return(@Do(@Command([EditGotoField];"Gender");			@Prompt([Ok];"Missing Value"; "Please insert 'Gender' before proceeding!")));"");
@If (SalaryRange= ""; 	@Return(@Do(@Command([EditGotoField];"SalaryRange");@Prompt([Ok];"Missing Value"; "Please insert 'Salary Range' before proceeding!")));"");

FIELD SubmitDate		:= @Now;
FIELD SubmittedBy	:= @Name([CN];@UserName);
FIELD CA 					:= "Submitted";
FIELD HODName		:="";
FIELD HODDate			:="";
FIELD Status1 				:= "";
FIELD DivName			:="";
FIELD DivDate				:="";
FIELD Status2 				:= "";
FIELD AckName			:="";
FIELD AckDate			:="";
FIELD Status3 				:= "";
FIELD HRName			:="";
FIELD HRDate				:="";
FIELD Status4 				:= "";
FIELD COOName		:="";
FIELD COODate			:="";
FIELD Status5 				:= "";
FIELD EDName			:="";
FIELD EDDate				:="";
FIELD Status6 				:= "";

@If(Rej1=NULL;@SetField("Rej1";1);NULL);
@If(Rej2=NULL;@SetField("Rej2";1);NULL);
@If(Rej3=NULL;@SetField("Rej3";1);NULL);
@If(Rej4=NULL;@SetField("Rej4";1);NULL);
@If(Rej5=NULL;@SetField("Rej5";1);NULL);
@If(Rej6=NULL;@SetField("Rej6";1);NULL);

@Command([FileSave]);
@MailSend(HOD;HR:CC;NULL;"New " + @DbTitle + " - " + Dept;NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument]; "1");

@If(WDReason = ""; @Return(@Do(@Command([EditGotoField];"WDReason") ;@Prompt([Ok];"Missing Value"; "Please state the reason!")));"");

FIELD CA				:="Withdrawn";
FIELD WDDate 	:=@Today;
FIELD WDBy 		:=@Name([CN];@UserName);

@Command([FileSave]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

