@If (Rej1=1 & Comment1 = ""; @Return(@Do(@Command([EditGotoField];"Comment1");			@Prompt([Ok];"Missing Value"; "Please state the reason before proceeding (1)!")));"");
@If (Rej1=2 & Comment2 = ""; @Return(@Do(@Command([EditGotoField];"Comment2");			@Prompt([Ok];"Missing Value"; "Please state the reason before proceeding (2)!")));"");
