@If (Rej1=4 & Comment4 = ""; @Return(@Do(@Command([EditGotoField];"Comment4");			@Prompt([Ok];"Missing Value"; "Please state the reason before proceeding (4)!")));"");

FIELD HODName 	:= @Name([CN];@UserName);
FIELD HODDate	:= @Now;
FIELD CA 				:= "RejectedHOD";
FIELD Status1 		:= "0";
FIELD Rej1 			:= Rej1+1;

@MailSend(DocAuthor;HR;NULL;@DbTitle+" Rejected by HOD - " + Dept;NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

